"""Tests for check_config on configs generated by AlpaSim's real wizard (no GPU, no Docker).

Run inside AlpaSim's environment, like test_logged_model.py. The wizard runs with
`deploy=docker_build_only wizard.run_method=NONE`, so it only writes configs.
"""

import os
import shutil
import subprocess
from pathlib import Path

import pytest

from alpasim_vla_on_edge.check_config import check_gpu_layout, check_run

REPO = Path(__file__).resolve().parents[3]
ALPASIM = REPO / "third_party/alpasim"
TOPOLOGIES = {"1gpu": "1gpu", "2gpu": "vla_on_edge_2gpu"}  # our layout name -> AlpaSim topology option


def generate_configs(log_dir: Path, driver: str, overrides: str, layout: str) -> Path:
    """Run AlpaSim's wizard in generate-only mode with our Hydra overrides."""
    command = [
        shutil.which("uv"), "run", "--no-sync", "alpasim_wizard", "deploy=docker_build_only",
        f"topology={TOPOLOGIES[layout]}", f"driver={driver}",
        f"hydra.searchpath=[file://{REPO}/configs/alpasim]", f"+vla_on_edge={overrides}",
        "wizard.run_method=NONE", f"wizard.log_dir={log_dir}",
    ]
    environment = {**os.environ, "VLA_ON_EDGE_REPO": str(REPO), "VLA_ON_EDGE_GIT_COMMIT": "test"}
    completed = subprocess.run(command, cwd=ALPASIM, env=environment, stdin=subprocess.DEVNULL,
                               capture_output=True, text=True, timeout=300)
    assert completed.returncode == 0, completed.stdout[-3000:] + completed.stderr[-3000:]
    return log_dir


needs_wizard = pytest.mark.skipif(shutil.which("uv") is None or not ALPASIM.exists(), reason="needs uv and AlpaSim")


@needs_wizard
@pytest.mark.parametrize("layout", ["1gpu", "2gpu"])
def test_alpamayo2_super_wrapper_configs_pass(tmp_path, layout):
    log_dir = generate_configs(tmp_path / "run", "alpamayo2", "alpamayo2_super", layout)
    assert check_run(log_dir, "alpamayo2_super", layout, builtin=False) == []
    # The other model or the other layout is caught.
    assert any("model_type" in problem for problem in check_run(log_dir, "alpamayo1_5", layout, builtin=False))
    other_layout = "1gpu" if layout == "2gpu" else "2gpu"
    assert any("renderer GPUs" in problem for problem in check_run(log_dir, "alpamayo2_super", other_layout, False))


@needs_wizard
def test_alpamayo2_builtin_stage_1_configs_pass(tmp_path):
    log_dir = generate_configs(tmp_path / "run", "alpamayo2", "builtin_offline", "2gpu")
    assert check_run(log_dir, "alpamayo2_super", "2gpu", builtin=True) == []


@needs_wizard
def test_alpamayo1_5_wrapper_configs_still_pass(tmp_path):
    log_dir = generate_configs(tmp_path / "run", "alpamayo1_5", "alpamayo1_5", "1gpu")
    assert check_run(log_dir, "alpamayo1_5", "1gpu", builtin=False) == []


def test_two_driver_services_on_the_model_gpu_are_rejected():
    def on(gpu_id):
        return {"deploy": {"resources": {"reservations": {"devices": [{"device_ids": [gpu_id]}]}}}}

    services = {"driver-0": on("0"), "driver-1": on("0"), "renderer-0": on("1"), "physics-0": on("1")}
    assert check_gpu_layout(services, "2gpu") == [
        "driver GPUs are [['0'], ['0']], expected one driver service on ['0'] (2gpu)"
    ]


@needs_wizard
def test_wrapper_runs_render_the_reasoning_overlay_and_stage_1_does_not(tmp_path):
    import yaml

    def layouts(log_dir):
        return yaml.safe_load((log_dir / "eval-config.yaml").read_text())["video"]["video_layouts"]

    wrapper = generate_configs(tmp_path / "wrapper", "alpamayo2", "alpamayo2_super", "1gpu")
    builtin = generate_configs(tmp_path / "builtin", "alpamayo2", "builtin_offline", "1gpu")
    assert layouts(wrapper) == ["DEFAULT", "REASONING_OVERLAY"]
    assert layouts(builtin) == ["DEFAULT"]
